import * as THREE from "three";

import { parseMcmeta } from "./parseMcmeta";

const VANILLA_WIDTH = 64;
const VANILLA_HEIGHT = 32;

const LAYOUTS: Array<[number, number]> = [
  [64, 32],
  [22, 17],
  [46, 22],
];

function capeScale(width: number, height: number): number | null {
  for (const [w, h] of LAYOUTS) {
    if (width * h === height * w) return width / w;
  }
  return null;
}

function frameHeight(image: { width: number; height: number }, mcmeta: unknown) {
  const parsed = mcmeta ? parseMcmeta(mcmeta) : null;
  const frames = parsed?.frames?.length ?? 0;
  return frames > 1 ? image.height / frames : image.height;
}

export function normalizeCapeTexture(
  texture: THREE.Texture,
  mcmeta?: unknown
): THREE.Texture | null {
  const image = texture.image as CanvasImageSource & {
    width?: number;
    height?: number;
  };
  if (!image?.width || !image?.height) return null;

  const width = image.width;
  const height = frameHeight(image as { width: number; height: number }, mcmeta);
  const scale = capeScale(width, height);
  if (scale === null) return null;
  if (width === VANILLA_WIDTH * scale && height === VANILLA_HEIGHT * scale) {
    return null;
  }

  const canvas = document.createElement("canvas");
  canvas.width = VANILLA_WIDTH * scale;
  canvas.height = VANILLA_HEIGHT * scale;

  const ctx = canvas.getContext("2d");
  if (!ctx) return null;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(image, 0, 0, width, height, 0, 0, width, height);

  const normalized = new THREE.CanvasTexture(canvas);
  normalized.flipY = texture.flipY;
  normalized.colorSpace = texture.colorSpace;
  normalized.magFilter = THREE.NearestFilter;
  normalized.minFilter = THREE.NearestFilter;
  normalized.generateMipmaps = false;
  normalized.needsUpdate = true;
  return normalized;
}
